<script setup lang="ts">
import {computed} from 'vue'
const props=defineProps<{rows:{label:string;value:number}[];details:{id:number;equipment_name:string;status:string;availability:string}[]}>()
const total=computed(()=>props.rows.reduce((n,r)=>n+Number(r.value),0))
const colors:Record<string,string>={'可用':'#22a06b','待处理':'#e89b22','维修中':'#4285db','报废':'#dc5261','停用或其他':'#94a3b8'}
</script>
<template><section class="panel"><div class="flex flex-wrap justify-between gap-3"><h2 class="font-semibold">设备状态</h2><span class="text-sm text-slate-500">当前设备快照 · 随车间筛选，每30秒刷新 · 共{{total}}台</span></div><p class="text-sm text-slate-500 mt-2">读取设备台账和未结束的维修单；不代表设备传感器实时在线率。</p><div v-if="total" class="flex h-9 rounded overflow-hidden mt-4" role="img" :aria-label="rows.map(r=>`${r.label}${r.value}台`).join('，')"><div v-for="r in rows" :key="r.label" :style="{width:`${r.value/total*100}%`,background:colors[r.label]||'#94a3b8'}" class="text-white text-xs flex items-center justify-center" :title="`${r.label} ${r.value}台`">{{r.value}}</div></div><p v-else class="p-5 text-slate-500">该范围暂无设备，请先维护设备和工作站关联。</p><ul class="flex flex-wrap gap-5 mt-3 text-sm"><li v-for="r in rows" :key="r.label"><span class="inline-block w-3 h-3 rounded mr-1" :style="{background:colors[r.label]||'#94a3b8'}"></span>{{r.label}} {{r.value}}台</li></ul><details class="mt-3 text-sm"><summary class="cursor-pointer text-blue-600">核对设备明细</summary><table class="w-full mt-3"><thead><tr class="text-left"><th>设备</th><th>台账状态</th><th>当前可用性</th></tr></thead><tbody><tr v-for="e in details" :key="e.id" class="border-t"><td class="py-2">{{e.equipment_name}}</td><td>{{e.status}}</td><td>{{e.availability}}</td></tr></tbody></table></details></section></template>
